    {"id": 1, "claim": "In a DFS tree of an undirected graph, every non-tree edge (back edge) connects a vertex to one of its ancestors.", "evidence": "Standard property of DFS in undirected graphs: no cross edges exist.", "weight": 1.0, "depends_on": []},
